class Solution { public:int minimumAverageDifference(vector<int>& nums){long long total=accumulate(nums.begin(),nums.end(),0LL),prefix=0,best=LLONG_MAX;int answer=0;for(int i=0;i<(int)nums.size();++i){prefix+=nums[i];long long left=prefix/(i+1),right=i==(int)nums.size()-1?0:(total-prefix)/(nums.size()-i-1),difference=llabs(left-right);if(difference<best){best=difference;answer=i;}}return answer;} };
